---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function ()
	-- ironbar taskbar (replaces the old eww bar; `eww open bar` no longer runs).
	-- The eww daemon stays up purely for the SUPER+A mouse-accel picker.
	-- hl.exec_cmd("hyprpanel")
	hl.exec_cmd("ironbar")
	-- Ghostty quick-terminal daemon (SUPER+Q, see the bind further down).
	-- It MUST run inside a systemd *scope* named app-<app-id>-<tag>.scope:
	-- xdg-desktop-portal derives the app id from the cgroup, and rejects the
	-- GlobalShortcuts request with "An app id is required" otherwise. A bare
	-- `ghostty` from here lands in session-N.scope, and a transient .service
	-- unit is not recognised either -- both were tested, only the scope works.
	-- The packaged app-com.mitchellh.ghostty.service is Type=dbus and fails
	-- whenever another ghostty already owns the bus name, so it is not used.
	hl.exec_cmd(os.getenv("HOME") .. "/bin/ghostty-quick-toggle --start-only")
	hl.exec_cmd("easyeffects --gapplication-service")
	hl.exec_cmd("ghostty --class=com.scratch.ghostty")
	hl.exec_cmd("hypridle")
	hl.exec_cmd("hyprpaper")
	-- Random wallpaper. `hyprctl hyprpaper preload` returns "invalid hyprpaper
	-- request" on hyprpaper 0.8.4, so it's dropped: `wallpaper` loads the image
	-- itself. The retry loop covers the daemon not being up yet after 1s.
	hl.exec_cmd("bash -c 'WP=$(find ~/Pictures/wallpapers -type f | shuf -n1); for i in 1 2 3 4 5; do sleep 1; hyprctl hyprpaper wallpaper \",$WP\" && break; done'")
end)


