-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Environment-variables/

--
-- GPU SPECIFIC
--
-- Detected from each card's PCI vendor ID in sysfs, the same way setup-arch.sh
-- picks its VA-API packages. Keeping it dynamic means this file stays portable
-- across machines: nothing vendor-specific is exported on absent hardware.
local gpu = {}
for i = 0, 15 do
	local f = io.open("/sys/class/drm/card" .. i .. "/device/vendor", "r")
	if f then
		local id = f:read("l")
		f:close()
		if id then gpu[id] = true end
	end
end
local amd, intel, nvidia = gpu["0x1002"], gpu["0x8086"], gpu["0x10de"]

-- A session exposes exactly one VA-API driver, so on a hybrid machine the iGPU
-- wins: it decodes video at a fraction of the dGPU's power draw.
if intel then
	-- intel-media-driver, Broadwell (Gen8, 2014) and newer. Older iGPUs need
	-- libva-intel-driver and "i965" here instead.
	hl.env("LIBVA_DRIVER_NAME", "iHD")
elseif amd then
	-- mesa's gallium driver. Pre-GCN (Northern Islands and older) wants "r600".
	hl.env("LIBVA_DRIVER_NAME", "radeonsi")
elseif nvidia then
	-- Requires libva-nvidia-driver, which maps VA-API onto NVDEC. Without that
	-- package installed this var just leaves VA-API broken, falling back to
	-- software decode. NVD_BACKEND=direct is required by 0.0.10 and newer.
	hl.env("LIBVA_DRIVER_NAME", "nvidia")
	hl.env("NVD_BACKEND", "direct")
end

-- mesa deleted its VDPAU state tracker (the mesa-vdpau package no longer exists
-- at all), so VDPAU on AMD/Intel now has to route through libvdpau-va-gl, which
-- re-implements it on top of the VA-API driver selected above.
if amd or intel then
	hl.env("VDPAU_DRIVER", "va_gl")
end

if nvidia then
	-- Only correct when NVIDIA is the *only* GPU: on a hybrid laptop these force
	-- every GL client onto the dGPU instead of letting it idle.
	if not (amd or intel) then
		hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
		hl.env("GBM_BACKEND", "nvidia-drm")
	end
	-- The old WLR_NO_HARDWARE_CURSORS was dropped with wlroots itself; aquamarine
	-- replaced it with cursor:use_cpu_buffer, already defaulting to auto (2).
end

-- Skip compositing entirely and hand a fullscreen window's buffer straight to
-- the display controller. Pairs with general:allow_tearing above and the
-- immediate = true game rules further down.
hl.config({
	render = {
		direct_scanout = 2, -- 0 disable | 1 enable | 2 auto
	},
})

