---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd("ghostty --class=com.scratch.ghostty"))
-- Ghostty quick terminal. The id comes from `hyprctl globalshortcuts`; ghostty
-- derives it from its own `keybind = global:super+q=...` trigger, so changing
-- that line in ~/.config/ghostty/config changes the id here too.
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(os.getenv("HOME") .. "/bin/ghostty-quick-toggle"))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(browser))
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd(os.getenv("HOME") .. "/.config/eww/scripts/launch.sh")) -- mouse accel profile picker
hl.bind(mainMod .. " + K", hl.dsp.exec_cmd(kolor))
hl.bind(mainMod .. " + masculine", hl.dsp.exec_cmd(calc))
hl.bind(mainMod .. " + C", hl.dsp.window.close())
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd(music))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + Space", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.exec_cmd(os.getenv("HOME") .. "/bin/zellij-picker")) -- zellij session picker
hl.bind("CTRL + Print", hl.dsp.exec_cmd("hyprshot -m region"))
hl.bind("Print", hl.dsp.exec_cmd("hyprpicker -a"))
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
	local key = i % 10 -- 10 maps to key 0
	hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
	hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })

hl.bind("Pause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })

-- volume (AltGr + Up/Down)
hl.bind("MOD5 + up",   hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true })
hl.bind("MOD5 + down", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { locked = true })

-- skip tracks (AltGr + Left/Right)
hl.bind("MOD5 + right", hl.dsp.exec_cmd("playerctl next"),     { locked = true })
hl.bind("MOD5 + left",  hl.dsp.exec_cmd("playerctl previous"), { locked = true })

hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special("term"))

hl.window_rule({ match = { class = "^(com.scratch.ghostty)$" }, workspace = "special:term" })
hl.window_rule({ match = { class = "^(com.scratch.ghostty)$" }, float = true })
hl.window_rule({ match = { class = "^(com.scratch.ghostty)$" }, size = { "monitor_w*0.7", "monitor_h*0.6" } })
hl.window_rule({ match = { class = "^(com.scratch.ghostty)$" }, center = true })

hl.window_rule({  match = { class = "CheatBreaker 1.7.10" }, immediate = true, fullscreen = true })
hl.window_rule({  match = { class = "CheatBreaker 1.8.9" }, immediate = true, fullscreen = true })
hl.window_rule({  match = { class = "^Minecraft.*$" }, immediate = true, fullscreen = true })
hl.window_rule({  match = { class = "zen" }, fullscreen = true })

hl.bind(mainMod .. " + R", hl.dsp.submap("resize"))

hl.define_submap("resize", function()
	hl.bind("right", hl.dsp.window.resize({ x = "100", y = "0" }), { repeating = true })
	hl.bind("left",  hl.dsp.window.resize({ x = "-100", y = "0" }), { repeating = true })
	hl.bind("up",    hl.dsp.window.resize({ x = "0", y = "-100" }), { repeating = true })
	hl.bind("down",  hl.dsp.window.resize({ x = "0", y = "100" }), { repeating = true })
	hl.bind("escape", hl.dsp.submap("reset"))
end)

-- Keyboard control for the eww mouse-accel picker (entered by launch.sh)
hl.define_submap("accel", function()
	local nav = os.getenv("HOME") .. "/.config/eww/scripts/nav.sh"
	hl.bind("up",     hl.dsp.exec_cmd(nav .. " move up"))
	hl.bind("k",      hl.dsp.exec_cmd(nav .. " move up"))
	hl.bind("down",   hl.dsp.exec_cmd(nav .. " move down"))
	hl.bind("j",      hl.dsp.exec_cmd(nav .. " move down"))
	hl.bind("Return", hl.dsp.exec_cmd(nav .. " confirm"))
	hl.bind("space",  hl.dsp.exec_cmd(nav .. " confirm"))
	hl.bind("1",      hl.dsp.exec_cmd(nav .. " apply adaptive"))
	hl.bind("a",      hl.dsp.exec_cmd(nav .. " apply adaptive"))
	hl.bind("2",      hl.dsp.exec_cmd(nav .. " apply custom"))
	hl.bind("c",      hl.dsp.exec_cmd(nav .. " apply custom"))
	hl.bind("escape", hl.dsp.exec_cmd(nav .. " cancel"))
	hl.bind("q",      hl.dsp.exec_cmd(nav .. " cancel"))
end)

