	name  = "rofi-blur",
	match = { namespace = "^rofi$" },
	blur         = true,
	ignore_alpha = 0.2,
	dim_around   = true,
})

hl.layer_rule({
	name  = "zellij-picker-blur",
	match = { namespace = "^zellij-picker$" },
	blur         = true,
	ignore_alpha = 0.2,
	dim_around   = true,
})

-- Hyprland-run windowrule
hl.window_rule({
	name  = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move  = "20 monitor_h-120",
	float = true,
})
